12	import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
13	
14	/**
15	 * 仅在嵌入式 H2（MODE=MySQL）下自动执行 schema.sql 建表并写入合成数据；
16	 * 历史 compose/MySQL 入口的数据源不受本初始化器影响。
17	 */
18	@Configuration(proxyBeanMethods = false)
19	public class H2SchemaInitConfig {
20	
21	    /**
22	     * 数据源 URL 指向 H2 时生效。
23	     */
24	    static class H2UrlCondition implements Condition {
25	
26	        @Override
27	        public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {
28	            String url = context.getEnvironment().getProperty("spring.datasource.url");
29	            return url != null && url.startsWith("jdbc:h2:");
30	        }
31	    }
32	
33	    @Bean
34	    @Conditional(H2UrlCondition.class)
35	    public DataSourceInitializer h2DataSourceInitializer(DataSource dataSource) {
36	        DataSourceInitializer initializer = new DataSourceInitializer();
37	        initializer.setDataSource(dataSource);
38	        ResourceDatabasePopulator populator = new ResourceDatabasePopulator();
39	        populator.addScript(new ClassPathResource("schema.sql"));
40	        populator.setContinueOnError(false);
41	        initializer.setDatabasePopulator(populator);
42	        return initializer;
43	    }
44	}
