 */
@Repository
public class LatchRepository {

    private final JdbcTemplate jdbcTemplate;

    public LatchRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 锁定指定航班闩锁行（不存在则创建）。必须在事务内调用。
