CREATE TABLE IF NOT EXISTS deicing_bay (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    bay_code    VARCHAR(32)  NOT NULL,
    bay_name    VARCHAR(64)  NOT NULL,
