    public int sumOpenBorrow(String fluidCode) {
        return sum("""
                SELECT COALESCE(SUM(quantity), 0) FROM borrow_order
                WHERE fluid_code = ? AND status = 'OPEN'
                """, fluidCode);
    }

    // ---- 液罐未归还占位 --------------------------------------------------------

    public void insertTankOpen(String tankId, String requestId, Instant now) {
